"""Live Eval case schema. Human Gold is never generated by a model.

v2 Human Gold (the only default annotation template):

    Locate  → kernel_targets
    Estimate → cognitive_effects + expected_delta
    Route   → attention_state + processing_modes
"""

from __future__ import annotations

from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator

GoldStatus = Literal["LABELED", "UNLABELED"]
SourceKind = Literal[
    "news",
    "paper",
    "technical_blog",
    "field_observation",
    "investment",
    "hype",
    "cross_domain_analogy",
    "wechat",
    "github",
    "company_blog",
]
CognitiveTask = Literal[
    "topic_relevance",
    "structural_relevance",
    "belief_conflict",
    "decision_relevance",
    "evidence_verification",
]

ATTENTION_STATES = ("DROP", "AWARE", "WATCH", "ENGAGE")
PROCESSING_MODES = ("SCAN", "LEARN", "VERIFY", "DEEP_DIVE", "SYNTHESIZE")
COGNITIVE_EFFECTS = ("REINFORCE", "CHALLENGE", "REFINE", "OPEN_NEW", "NO_MATERIAL_CHANGE")
KERNEL_TARGET_NONE = "NONE"

# Default annotation template. Choice / multi-select / free-text only.
HUMAN_GOLD_TEMPLATE = {
    "attention_state": [],  # multi-select from ATTENTION_STATES (acceptable set)
    "processing_modes": [],  # multi-select from PROCESSING_MODES
    "kernel_targets": [],  # Kernel titles/ids, or ["NONE"]
    "cognitive_effects": [],  # multi-select from COGNITIVE_EFFECTS; zip with targets when same length
    "expected_delta": "",  # free text: what absorbing this should add/correct/form
}


class LiveSource(BaseModel):
    model_config = ConfigDict(extra="ignore")

    type: str | None = None
    title: str | None = None
    url: str | None = None
    local_file: str | None = None
    text: str | None = None


class DynamicsEffectGold(BaseModel):
    """Legacy Dynamics Gold pair. Optional compatibility only — not part of the default template."""

    model_config = ConfigDict(extra="ignore")

    target_kernel: str | None = None
    acceptable_effects: list[str] = Field(default_factory=list)
    effect: str | None = None
    min_change_magnitude: float | None = None
    max_change_magnitude: float | None = None
    max_epistemic_strength: float | None = None
    min_epistemic_strength: float | None = None


class HumanGold(BaseModel):
    """v2 Human Gold. Five core fields; everything else is legacy optional."""

    model_config = ConfigDict(extra="ignore")

    attention_state: list[str] = Field(
        default_factory=list,
        description="Acceptable Attention states (multi-select): DROP | AWARE | WATCH | ENGAGE",
    )
    processing_modes: list[str] = Field(
        default_factory=list,
        description="Acceptable Processing Modes (multi-select): SCAN | LEARN | VERIFY | DEEP_DIVE | SYNTHESIZE",
    )
    kernel_targets: list[str] = Field(
        default_factory=list,
        description='Kernel node titles/ids to locate, or ["NONE"]',
    )
    cognitive_effects: list[str] = Field(
        default_factory=list,
        description="Acceptable Cognitive Effects (multi-select): REINFORCE | CHALLENGE | REFINE | OPEN_NEW | NO_MATERIAL_CHANGE",
    )
    expected_delta: str | None = Field(
        default=None,
        description="Free text: what absorbing this information should add, correct, or form.",
    )

    # Legacy optional — readable, not part of the default template.
    acceptable_modes: list[str] = Field(default_factory=list)
    must_match_kernel: list[str] = Field(default_factory=list)
    should_match_kernel: list[str] = Field(default_factory=list)
    forbidden_kernel: list[str] = Field(default_factory=list)
    key_claims: list[str] = Field(default_factory=list)
    key_observations: list[str] = Field(default_factory=list)
    expected_delta_concepts: list[str] = Field(default_factory=list)
    forbidden_conclusions: list[str] = Field(default_factory=list)
    expected_effects: list[DynamicsEffectGold] = Field(default_factory=list)
    forbidden_effects: list[DynamicsEffectGold] = Field(default_factory=list)
    delta_rubric: int | None = Field(default=None, ge=0, le=3)
    notes: str | None = None

    @model_validator(mode="after")
    def _promote_legacy(self) -> HumanGold:
        if not self.processing_modes and self.acceptable_modes:
            self.processing_modes = list(self.acceptable_modes)
        if not self.expected_delta and self.expected_delta_concepts:
            self.expected_delta = "; ".join(s for s in self.expected_delta_concepts if s) or None
        if not self.kernel_targets:
            if self.must_match_kernel:
                self.kernel_targets = list(self.must_match_kernel)
            elif self.expected_effects:
                self.kernel_targets = [e.target_kernel or KERNEL_TARGET_NONE for e in self.expected_effects]
        if not self.cognitive_effects and self.expected_effects:
            kinds: list[str] = []
            for item in self.expected_effects:
                kinds.extend(item.acceptable_effects or [])
                if item.effect:
                    kinds.append(item.effect)
            self.cognitive_effects = kinds
        return self

    def has_core_labels(self) -> bool:
        return bool(
            self.attention_state
            or self.processing_modes
            or self.kernel_targets
            or self.cognitive_effects
            or (self.expected_delta or "").strip()
        )

    def has_legacy_labels(self) -> bool:
        return bool(
            self.must_match_kernel
            or self.key_claims
            or self.key_observations
            or self.expected_effects
            or self.acceptable_modes
            or self.expected_delta_concepts
        )

    def target_effect_pairs(self) -> list[tuple[str, list[str]]]:
        """Locate+Estimate pairs. Same-length lists zip; otherwise effects are the acceptable set for each target."""
        if self.expected_effects:
            pairs: list[tuple[str, list[str]]] = []
            for item in self.expected_effects:
                kinds = list(item.acceptable_effects or [])
                if item.effect:
                    kinds.append(item.effect)
                pairs.append((item.target_kernel or KERNEL_TARGET_NONE, kinds))
            return pairs
        targets = [t for t in self.kernel_targets if t]
        kinds = [k for k in self.cognitive_effects if k]
        if not targets and not kinds:
            return []
        if not targets:
            return [(KERNEL_TARGET_NONE, kinds)]
        if kinds and len(targets) == len(kinds):
            return [(target, [kind]) for target, kind in zip(targets, kinds)]
        return [(target, kinds) for target in targets]


class LiveCase(BaseModel):
    model_config = ConfigDict(extra="ignore")

    id: str
    source: LiveSource = Field(default_factory=LiveSource)
    kernel_fixture: str | None = "mvp"
    source_kind: SourceKind | None = None
    cognitive_tasks: list[CognitiveTask] = Field(default_factory=list)
    human_gold: HumanGold | None = None
    gold_status: GoldStatus = "UNLABELED"
    notes: str | None = None


class LiveManifest(BaseModel):
    model_config = ConfigDict(extra="ignore")

    name: str = "raos-live-eval"
    cases: list[LiveCase] = Field(default_factory=list)


def gold_status_of(case: LiveCase) -> GoldStatus:
    if case.gold_status == "LABELED":
        return "LABELED"
    gold = case.human_gold
    if gold is None:
        return "UNLABELED"
    if gold.has_core_labels() or gold.has_legacy_labels():
        return "LABELED"
    return "UNLABELED"


def dump_human_gold(gold: HumanGold | None) -> dict[str, Any] | None:
    """Persist core v2 fields; include non-empty legacy keys for old runners."""
    if gold is None:
        return None
    payload: dict[str, Any] = {
        "attention_state": list(gold.attention_state),
        "processing_modes": list(gold.processing_modes),
        "kernel_targets": list(gold.kernel_targets),
        "cognitive_effects": list(gold.cognitive_effects),
        "expected_delta": gold.expected_delta,
    }
    legacy = {
        "acceptable_modes": gold.acceptable_modes,
        "must_match_kernel": gold.must_match_kernel,
        "should_match_kernel": gold.should_match_kernel,
        "forbidden_kernel": gold.forbidden_kernel,
        "key_claims": gold.key_claims,
        "key_observations": gold.key_observations,
        "expected_delta_concepts": gold.expected_delta_concepts,
        "forbidden_conclusions": gold.forbidden_conclusions,
        "expected_effects": [e.model_dump() for e in gold.expected_effects],
        "forbidden_effects": [e.model_dump() for e in gold.forbidden_effects],
        "delta_rubric": gold.delta_rubric,
        "notes": gold.notes,
    }
    for key, value in legacy.items():
        if value in (None, [], ""):
            continue
        payload[key] = value
    return payload
